const cfg = $input.first().json;

function bool(value) {
  return value === true || String(value).toLowerCase() === 'true';
}

function hasRealValue(value) {
  const text = String(value || '').trim();
  return text !== '' && !text.includes('COLE_AQUI');
}

const limit = Math.max(1, Math.min(Number(cfg.limit || 10), 50));
const sources = [];

if (bool(cfg.mercadoLivreEnabled) && hasRealValue(cfg.mercadoLivreAccessToken)) {
  const query = String(cfg.mercadoLivreQuery || '').trim();
  sources.push({
    json: {
      source_kind: 'mercadolivre',
      source: 'Mercado Livre',
      query,
      currency: cfg.currency || 'BRL',
      url: `https://api.mercadolibre.com/sites/MLB/search?q=${encodeURIComponent(query)}&limit=${limit}&sort=price_asc`,
      authHeader: `Bearer ${String(cfg.mercadoLivreAccessToken).trim()}`
    }
  });
}

if (bool(cfg.amazonEnabled) && hasRealValue(cfg.amazonApiUrl)) {
  const query = String(cfg.amazonQuery || '').trim();
  const url = String(cfg.amazonApiUrl)
    .replaceAll('{{query}}', encodeURIComponent(query))
    .replaceAll('{{limit}}', String(limit));
  sources.push({
    json: {
      source_kind: 'amazon',
      source: 'Amazon',
      query,
      currency: cfg.currency || 'BRL',
      url,
      authHeader: hasRealValue(cfg.amazonAuthHeader) ? String(cfg.amazonAuthHeader).trim() : ''
    }
  });
}

if (sources.length === 0 && bool(cfg.demoFallbackEnabled)) {
  sources.push({
    json: {
      source_kind: 'generic',
      source: 'Fonte demo',
      query: 'produtos de teste',
      currency: cfg.currency || 'BRL',
      url: `https://fakestoreapi.com/products?limit=${Math.min(limit, 10)}`,
      authHeader: ''
    }
  });
}

return sources;

const sourceItems = $('Preparar fontes').all();
const inputItems = $input.all();
const output = [];

function valueAt(value, path) {
  return path.split('.').reduce((current, key) => {
    if (current === undefined || current === null) return undefined;
    if (/^\d+$/.test(key)) return current[Number(key)];
    return current[key];
  }, value);
}

function pick(record, paths) {
  for (const path of paths) {
    const value = valueAt(record, path);
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return '';
}

function firstArray(payload, sourceKind) {
  if (Array.isArray(payload)) return payload;
  if (sourceKind === 'mercadolivre') return Array.isArray(payload?.results) ? payload.results : [];
  if (sourceKind === 'amazon') {
    const candidates = [
      payload?.SearchResult?.Items,
      payload?.searchResult?.items,
      payload?.items,
      payload?.Items,
      payload?.data?.items,
      payload?.data?.SearchResult?.Items
    ];
    return candidates.find(Array.isArray) || [];
  }
  const candidates = [payload?.results, payload?.items, payload?.data, payload?.products, payload?.ads, payload?.data?.results, payload?.data?.items];
  return candidates.find(Array.isArray) || [];
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const cleaned = String(value)
    .replace(/\s/g, '')
    .replace(/R\$/gi, '')
    .replace(/\./g, '')
    .replace(',', '.')
    .replace(/[^0-9.-]/g, '');
  const number = Number(cleaned);
  return Number.isFinite(number) ? number : null;
}

function normalizeRecord(record, source) {
  const sourceKind = source.source_kind;
  if (sourceKind === 'mercadolivre') {
    return {
      item_id: String(pick(record, ['id'])).trim(),
      title: String(pick(record, ['title'])).trim(),
      price: toNumber(pick(record, ['price'])),
      item_url: String(pick(record, ['permalink'])).trim(),
      image_url: String(pick(record, ['thumbnail', 'pictures.0.url'])).trim(),
      seller: String(pick(record, ['seller.nickname', 'seller.id'])).trim(),
      availability: String(pick(record, ['available_quantity', 'status'])).trim()
    };
  }

  if (sourceKind === 'amazon') {
    return {
      item_id: String(pick(record, ['ASIN', 'asin', 'id'])).trim(),
      title: String(pick(record, ['ItemInfo.Title.DisplayValue', 'itemInfo.title.displayValue', 'title', 'name'])).trim(),
      price: toNumber(pick(record, [
        'OffersV2.Listings.0.Price.Money.Amount',
        'Offers.Listings.0.Price.Amount',
        'offersV2.listings.0.price.money.amount',
        'offers.listings.0.price.amount',
        'price.amount',
        'price',
        'buybox.price'
      ])),
      item_url: String(pick(record, ['DetailPageURL', 'detailPageUrl', 'url', 'link'])).trim(),
      image_url: String(pick(record, [
        'Images.Primary.Large.URL',
        'Images.Primary.Medium.URL',
        'images.primary.large.url',
        'images.primary.medium.url',
        'image',
        'image_url'
      ])).trim(),
      seller: String(pick(record, ['OffersV2.Listings.0.MerchantInfo.Name', 'Offers.Listings.0.MerchantInfo.Name', 'seller', 'merchant'])).trim(),
      availability: String(pick(record, ['OffersV2.Listings.0.Availability.Message', 'Offers.Listings.0.Availability.Message', 'availability'])).trim()
    };
  }

  return {
    item_id: String(pick(record, ['id', 'item_id', 'sku', 'asin', 'url', 'permalink', 'link', 'title', 'name'])).trim(),
    title: String(pick(record, ['title', 'name', 'description'])).trim(),
    price: toNumber(pick(record, ['price', 'amount', 'current_price', 'sale_price', 'value', 'prices.price'])),
    item_url: String(pick(record, ['permalink', 'url', 'link', 'href'])).trim(),
    image_url: String(pick(record, ['thumbnail', 'image', 'picture', 'image_url', 'pictures.0.url'])).trim(),
    seller: String(pick(record, ['seller.nickname', 'seller_name', 'store_name'])).trim(),
    availability: String(pick(record, ['available_quantity', 'availability', 'status'])).trim()
  };
}

for (let index = 0; index < inputItems.length; index++) {
  const payload = inputItems[index].json;
  const source = sourceItems[index]?.json || {};
  if (!source.url || payload?.error || payload?.statusCode >= 400) continue;

  const records = firstArray(payload, source.source_kind);
  for (const record of records) {
    const normalized = normalizeRecord(record, source);
    if (!normalized.item_id || !normalized.title) continue;

    output.push({
      json: {
        checked_at: new Date().toISOString(),
        source: source.source,
        source_kind: source.source_kind,
        query: source.query,
        item_id: normalized.item_id,
        title: normalized.title,
        price: normalized.price,
        currency: source.currency || 'BRL',
        item_url: normalized.item_url,
        image_url: normalized.image_url,
        seller: normalized.seller,
        availability: normalized.availability,
        raw_json: JSON.stringify(record)
      }
    });
  }
}

return output;

const cfg = $('Configuracao geral').first().json;
const state = $getWorkflowStaticData('global');
state.itemsById = state.itemsById || {};

function money(value, currency) {
  if (value === null || value === undefined || value === '') return 'preco indisponivel';
  return `${currency} ${Number(value).toFixed(2)}`;
}

const minPercentChange = Number(cfg.minPercentChange || 0);
const now = new Date().toISOString();
const alerts = [];

for (const item of $input.all()) {
  const current = item.json;
  const stateKey = `${current.source}:${current.item_id}`;
  const previous = state.itemsById[stateKey];
  const previousPrice = previous?.price ?? null;
  const price = current.price ?? null;
  let eventType = null;
  let priceDiff = null;
  let percentDiff = null;

  if (!previous) {
    eventType = 'novo_anuncio';
  } else if (price !== null && previousPrice !== null && price !== previousPrice) {
    priceDiff = Number((price - previousPrice).toFixed(2));
    percentDiff = previousPrice === 0 ? null : Number(((priceDiff / previousPrice) * 100).toFixed(2));
    eventType = price < previousPrice ? 'queda_preco' : 'aumento_preco';
  }

  state.itemsById[stateKey] = {
    title: current.title,
    price,
    itemUrl: current.item_url,
    lastSeenAt: now,
    source: current.source,
    query: current.query
  };

  if (!eventType) continue;
  if (percentDiff !== null && Math.abs(percentDiff) < minPercentChange) continue;

  const eventLabel = eventType === 'novo_anuncio'
    ? 'Novo anuncio'
    : eventType === 'queda_preco'
      ? 'Queda de preco'
      : 'Aumento de preco';

  const previousLine = previous
    ? `Preco anterior: ${money(previousPrice, current.currency)}\nVariacao: ${priceDiff > 0 ? '+' : ''}${priceDiff} (${percentDiff > 0 ? '+' : ''}${percentDiff}%)\n`
    : '';

  const message = `[${current.source}] ${eventLabel}\n${current.title}\nBusca: ${current.query}\nPreco atual: ${money(price, current.currency)}\n${previousLine}${current.item_url ? `Link: ${current.item_url}` : 'Link indisponivel'}`;

  alerts.push({
    json: {
      checked_at: now,
      source: current.source,
      query: current.query,
      event_type: eventType,
      item_id: current.item_id,
      title: current.title,
      price,
      previous_price: previousPrice,
      price_diff: priceDiff,
      percent_diff: percentDiff,
      currency: current.currency,
      item_url: current.item_url,
      image_url: current.image_url,
      seller: current.seller,
      availability: current.availability,
      message,
      raw_json: current.raw_json,
      spreadsheet_id: cfg.spreadsheetId,
      sheet_name: cfg.sheetName,
      telegram_chat_id: cfg.telegramChatId,
      gmail_to: cfg.gmailTo
    }
  });
}

const keys = Object.keys(state.itemsById);
if (keys.length > 2000) {
  keys
    .sort((a, b) => String(state.itemsById[a].lastSeenAt).localeCompare(String(state.itemsById[b].lastSeenAt)))
    .slice(0, keys.length - 2000)
    .forEach(key => delete state.itemsById[key]);
}

state.lastExecutionAt = now;
return alerts;
